class DshMathView extends ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    this.plugin = plugin;
    this.offStatus = null;
    this.iframe = null;
  }

  getViewType() {
    return VIEW_TYPE;
  }

  getDisplayText() {
    return 'DSH数学笔记助手';
  }

  getIcon() {
    return 'message-square';
  }

  async onOpen() {
    this.contentEl.empty();
    this.contentEl.addClass('dsh-obsidian-math-view');
    this.statusRow = this.contentEl.createDiv({ cls: 'dsh-obsidian-math-status' });
    this.body = this.contentEl.createDiv({ cls: 'dsh-obsidian-math-body' });
    this.offStatus = this.plugin.service.onChange((status) => this.render(status));
    const status = await this.plugin.service.ensureStarted().then(() => this.plugin.service.status).catch(() => this.plugin.service.status);
    this.render(status);
  }

  render(status) {
    if (this.statusRow === undefined) return;
    if (status === 'running') {
      this.statusRow.empty();
      this.statusRow.style.display = 'none';
      const expectedSrc = `http://127.0.0.1:${this.plugin.settings.port}/`;
      if (this.iframe === null) {
        this.iframe = this.body.createEl('iframe', {
          cls: 'dsh-obsidian-math-iframe',
          attr: { src: expectedSrc }
        });
      } else if (this.iframe.getAttribute('src') !== expectedSrc) {
        this.iframe.setAttribute('src', expectedSrc);
      }
      return;
    }
    this.statusRow.style.display = '';
    if (this.iframe !== null) {
      this.iframe.remove();
      this.iframe = null;
    }
    this.statusRow.empty();
    const message = {
      starting: '正在启动 DeepSeek Harness 服务…',
      'missing-dsh': '未找到 dsh（DeepSeek Harness）。请打开插件设置并检测 dsh 安装路径。',
      error: 'dsh 服务启动失败。请打开插件设置查看日志。',
      stopped: 'dsh 服务已停止。',
      stopping: '正在停止服务…',
      unknown: '服务状态未知。'
    }[status] ?? '服务状态未知。';
    this.statusRow.setText(message);
    const actions = this.statusRow.createDiv({ cls: 'dsh-obsidian-math-actions' });
    const retry = actions.createEl('button', { text: '重试' });
    retry.addEventListener('click', async () => {
      this.render('starting');
      await this.plugin.service.ensureStarted().catch((error) => new Notice(String(error)));
      this.render(this.plugin.service.status);
    });
    const settings = actions.createEl('button', { text: '打开设置' });
    settings.addEventListener('click', () => this.plugin.openSettings());
  }

  async onClose() {
    if (this.offStatus !== null) this.offStatus();
  }
}

// ── memory panel view (memory v2 control surface, phase 1b) ─────────────────

const VIEW_TYPE_MEMORY = 'dsh-memory-panel';

const VERIFIED_BADGES = {
  'user-confirmed': '✅',
  'cross-referenced': '⚖️',
  'single-source': '❓'
};

/** Parse frontmatter scalars plus an optional block-style hook block. */
function parseMemoryFrontmatter(text) {
  const match = /^---\r?\n([\s\S]*?)\r?\n---/.exec(text ?? '');
  if (match === null) return { meta: {}, hook: null };
  const meta = {};
  const hook = {};
  let inHook = false;
  let lastListKey = null;
  for (const line of match[1].split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!inHook) {
      if (/^hook:\s*$/.test(trimmed)) { inHook = true; lastListKey = null; continue; }
      const pair = /^([A-Za-z_][\w-]*):\s*(.*)$/.exec(trimmed);
      if (pair !== null) meta[pair[1]] = pair[2].trim().replace(/^['"]|['"]$/g, '');
      continue;
    }
    if (line !== '' && !/^\s/.test(line)) { inHook = false; continue; }
    if (trimmed === '') continue;
    const pair = /^([A-Za-z_][\w-]*):\s*(.*)$/.exec(trimmed);
    if (pair !== null) {
      const key = pair[1];
      const value = pair[2].trim().replace(/^['"]|['"]$/g, '');
      if (value === '') { hook[key] = []; lastListKey = key; }
      else if (value.startsWith('[') && value.endsWith(']')) {
        hook[key] = value.slice(1, -1).split(',').map((part) => part.trim().replace(/^['"]|['"]$/g, '')).filter((part) => part !== '');
        lastListKey = null;
      } else { hook[key] = value; lastListKey = null; }
    } else if (trimmed.startsWith('- ') && lastListKey !== null) {
      if (!Array.isArray(hook[lastListKey])) hook[lastListKey] = [];
      hook[lastListKey].push(trimmed.slice(2).trim().replace(/^['"]|['"]$/g, ''));
    }
  }
  return { meta, hook: Object.keys(hook).length === 0 ? null : hook };
}

function titleOf(text, fallback) {
  const metaTitle = /^title:\s*(.+)$/m.exec(text ?? '')?.[1]?.trim();
  if (metaTitle !== undefined && metaTitle !== '') return metaTitle.replace(/^['"]|['"]$/g, '');
  const heading = /^#\s+(.+)$/m.exec(text ?? '')?.[1]?.trim();
  return heading ?? fallback;
}

function daysSinceText(dateStr) {
  const match = /^(\d{4})-(\d{2})-(\d{2})/.exec(dateStr ?? '');
  if (match === null) return '';
  const day = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
  const days = Math.floor((Date.now() - day.getTime()) / 86400000);
  return days > 0 ? `${days} 天前` : '今天';
}

/** Collect every memory-layer file under the vault for the panel. */
function collectMemoryState(vaultPath, filter) {
  const rel = (dir, name) => `${dir}/${name}`.replace(/\\/g, '/');
  const listDir = (dir) => {
    try {
      return readdirSync(join(vaultPath, dir), { withFileTypes: true })
        .filter((entry) => entry.isFile() && entry.name.endsWith('.md'))
        .map((entry) => entry.name);
    } catch {
      return [];
    }
  };
  const cardEntries = (dir) => listDir(dir)
    .filter((name) => name !== 'index.md' && !name.startsWith('_'))
    .map((name) => {
      const filePath = join(vaultPath, dir, name);
      let text = '';
      try {
        text = readFileSync(filePath, 'utf8');
      } catch {
        return null;
      }
      const { meta, hook } = parseMemoryFrontmatter(text);
      return {
        rel: rel(dir, name),
        name,
        title: titleOf(text, name.replace(/\.md$/, '')),
        type: meta.type ?? '',
        status: meta.status ?? 'active',
        updated: meta.updated ?? '',
        topic: meta.topic ?? '',
        hook,
        uses: Number.isFinite(Number(hook?.uses)) ? Number(hook.uses) : 0,
        successRate: Number.isFinite(Number(hook?.success_rate)) ? Number(hook.success_rate) : null,
        lastUsed: typeof hook?.last_used === 'string' ? hook.last_used : '',
        verified: typeof hook?.verified === 'string' ? hook.verified : null,
        operator: typeof hook?.operator === 'string' ? hook.operator : ''
      };
    })
    .filter((entry) => entry !== null);
  const matches = (entry) => filter === '' ||
    `${entry.title} ${entry.operator} ${entry.type} ${entry.topic}`.toLowerCase().includes(filter);
  const records = cardEntries('.deepseek/memory/records').filter(matches);
  const templates = cardEntries('.deepseek/memory/templates').filter(matches);
  const memos = listDir('.deepseek/inbox')
    .filter((name) => name !== 'index.md' && !name.startsWith('_'))
    .map((name) => {
      const filePath = join(vaultPath, '.deepseek', 'inbox', name);
      let text = '';
      try {
        text = readFileSync(filePath, 'utf8');
      } catch {
        return null;
      }
      const { meta } = parseMemoryFrontmatter(text);
      return {
        rel: rel('.deepseek/inbox', name),
        name,
        title: titleOf(text, name.replace(/\.md$/, '')),
        status: meta.status ?? 'inbox',
        updated: meta.updated ?? '',
        topic: meta.topic ?? ''
      };
    })
    .filter((entry) => entry !== null && (filter === '' || `${entry.title} ${entry.topic}`.toLowerCase().includes(filter)));
  const episodes = [];
  try {
    episodes.push(...readdirSync(join(vaultPath, '.deepseek', 'memory', 'episodes'), { withFileTypes: true })
      .filter((entry) => entry.isFile() && entry.name.endsWith('.md') && entry.name !== 'index.md' && !entry.name.startsWith('_'))
      .map((entry) => {
        const filePath = join(vaultPath, '.deepseek', 'memory', 'episodes', entry.name);
        let mtimeMs = 0;
        try {
          mtimeMs = statSync(filePath).mtimeMs;
        } catch {
          // keep 0
        }
        return { rel: rel('.deepseek/memory/episodes', entry.name), name: entry.name, mtimeMs };
      })
      .sort((a, b) => b.mtimeMs - a.mtimeMs));
  } catch {
    // episodes dir missing: stay empty
  }
  const profile = existsSync(join(vaultPath, '.deepseek', 'memory', 'profile.md'));
  const auditText = readAuditText(join(vaultPath, '.deepseek', 'cache', 'memory-audit.json'));
  return { records, templates, memos, episodes, profile, auditText };
}

function readAuditText(path) {
  try {
    const parsed = JSON.parse(readFileSync(path, 'utf8'));
    if (typeof parsed?.report === 'string' && parsed.report !== '') return parsed.report;
  } catch {
    // no report yet
  }
  return '';
}

/**
 * In-panel preview for hidden memory files. Obsidian's vault index excludes
 * dot-folders (verified in the 1.13.7 bundle: any path segment starting with
 * "." is hidden), so .deepseek files cannot be opened through openLinkText or
 * any TFile-based API. The panel reads them with node fs and shows them here.
 */
class MemoryPreviewModal extends Modal {
  constructor(app, title, content, fullPath) {
    super(app);
    this.titleText = title;
    this.contentText = content;
    this.fullPath = fullPath;
  }

  onOpen() {
    const { contentEl } = this;
    contentEl.addClass('dsh-memory-preview');
    contentEl.createEl('h3', { text: this.titleText });
    contentEl.createDiv({ cls: 'dsh-memory-preview-path', text: this.fullPath });
    contentEl.createEl('pre', { cls: 'dsh-memory-preview-body', text: this.contentText });
    const actions = contentEl.createDiv({ cls: 'dsh-memory-preview-actions' });
    const copy = actions.createEl('button', { text: '复制内容' });
    copy.addEventListener('click', async () => {
      try {
        await navigator.clipboard.writeText(this.contentText);
        new Notice('已复制到剪贴板');
      } catch (error) {
        new Notice('复制失败：' + String(error));
      }
    });
    const reveal = actions.createEl('button', { text: '在资源管理器中显示' });
    reveal.addEventListener('click', () => {
      try {
        const { shell } = window.require('electron');
        shell.showItemInFolder(this.fullPath);
      } catch (error) {
        new Notice(String(error));
      }
    });
    const openExternal = actions.createEl('button', { text: '用默认应用打开' });
    openExternal.addEventListener('click', async () => {
      try {
        const { shell } = window.require('electron');
        const result = await shell.openPath(this.fullPath);
        if (result !== '') new Notice('打开失败：' + result);
      } catch (error) {
        new Notice(String(error));
      }
    });
    const closeButton = actions.createEl('button', { text: '关闭' });
    closeButton.addEventListener('click', () => this.close());
  }

  onClose() {
    this.contentEl.empty();
  }
}

class MemoryView extends ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    this.plugin = plugin;
    this.filter = '';
  }

  getViewType() {
    return VIEW_TYPE_MEMORY;
  }

  getDisplayText() {
    return 'DSH 记忆面板';
  }

  getIcon() {
    return 'brain';
  }

  vaultPath() {
    return this.app.vault.adapter.getBasePath();
  }

  async onOpen() {
    writeDebugLog('[memory-view] onOpen start');
    const loading = this.contentEl.createDiv({ text: '记忆面板加载中…' });
    try {
      this.contentEl.addClass('dsh-memory-panel');
      const toolbar = this.contentEl.createDiv({ cls: 'dsh-memory-toolbar' });
      const search = toolbar.createEl('input', { type: 'search', placeholder: '搜索记忆卡（标题 / 算子 / 类型 / 主题）' });
      search.value = this.filter;
      search.addEventListener('input', () => {
        this.filter = search.value.trim().toLowerCase();
        this.render();
      });
      const refresh = toolbar.createEl('button', { text: '刷新' });
      refresh.addEventListener('click', () => this.render());
      const archive = toolbar.createEl('button', { text: '归档 >90 天事件' });
      archive.addEventListener('click', () => {
        try {
          const result = archiveOldEpisodes(this.plugin, 90);
          new Notice(result.moved > 0 ? `记忆维护：已归档 ${result.moved} 个旧事件文件` : '没有需要归档的旧事件');
        } catch (error) {
          new Notice(`记忆维护失败：${String(error)}`);
        }
        this.render();
      });
      this.body = this.contentEl.createDiv({ cls: 'dsh-memory-body' });
      this.render();
    } catch (error) {
      const detail = `记忆面板初始化失败：${String(error)}`;
      this.contentEl.setText(detail);
      this.plugin.service?.appendLog(detail + '\n' + (error?.stack ?? '(no stack)'));
      return;
    }
    loading.remove();
  }

  render() {
    writeDebugLog('[memory-view] render start');
    const body = this.body;
    if (body === undefined) return;
    body.empty();
    try {
      this.renderBody(body);
    } catch (error) {
      body.createDiv({ cls: 'dsh-memory-error', text: `记忆面板渲染失败：${String(error)}` });
    }
  }

  renderBody(body) {
    const state = collectMemoryState(this.vaultPath(), this.filter);
    const summary = [];
    if (state.profile) summary.push('画像 ✅');
    summary.push(`记录 ${state.records.length}`, `模板 ${state.templates.length}`, `备忘录 ${state.memos.length}`, `事件 ${state.episodes.length}`);
    body.createDiv({ cls: 'dsh-memory-summary', text: summary.join(' · ') });

    if (state.records.length > 0) {
      this.section(body, '记忆记录 .deepseek/memory/records/', state.records.length);
      for (const card of state.records) this.cardRow(body, card);
    }
    if (state.templates.length > 0) {
      this.section(body, '问题模板 .deepseek/memory/templates/', state.templates.length);
      for (const card of state.templates) this.cardRow(body, card);
    }
    if (state.memos.length > 0) {
      this.section(body, '备忘录 .deepseek/inbox/', state.memos.length);
      for (const memo of state.memos) this.memoRow(body, memo);
    }
    if (state.episodes.length > 0) {
      this.section(body, '事件时间线 .deepseek/memory/episodes/', state.episodes.length);
      const list = body.createDiv({ cls: 'dsh-memory-rows' });
      for (const episode of state.episodes.slice(0, 30)) {
        const row = list.createDiv({ cls: 'dsh-memory-row' });
        const link = row.createEl('a', { text: episode.name, cls: 'dsh-memory-title' });
        link.addEventListener('click', () => this.openNote(episode.rel));
        row.createDiv({ cls: 'dsh-memory-meta', text: new Date(episode.mtimeMs).toLocaleString('zh-CN', { hour12: false }) });
      }
      if (state.episodes.length > 30) {
        list.createDiv({ cls: 'dsh-memory-meta', text: `… 另有 ${state.episodes.length - 30} 个` });
      }
    }
    if (state.auditText !== '') {
      this.section(body, '记忆体检 .deepseek/cache/memory-audit.json', 1);
      body.createDiv({ cls: 'dsh-memory-audit' }).setText(state.auditText);
    }
    if (state.records.length === 0 && state.templates.length === 0 && state.memos.length === 0 && state.episodes.length === 0) {
      body.createDiv({ cls: 'dsh-memory-meta', text: this.filter === '' ? '记忆库还是空的。与助手对话后，记忆会按 AGENTS.md 逐层写入。' : '没有匹配的记忆。' });
    }
    // Diagnostics footer: always visible so an "empty" panel is self-explanatory.
    body.createDiv({ cls: 'dsh-memory-footer', text: `vault: ${this.vaultPath()} · 过滤: ${this.filter === '' ? '（无）' : this.filter}` });
    writeDebugLog('[memory-view] render done: 记录 ' + state.records.length + ' / 模板 ' + state.templates.length + ' / 备忘录 ' + state.memos.length + ' / 事件 ' + state.episodes.length);
  }

  section(parent, title, count) {
    const head = parent.createDiv({ cls: 'dsh-memory-section' });
    head.createSpan({ cls: 'dsh-memory-section-title', text: title });
    head.createSpan({ cls: 'dsh-memory-meta', text: String(count) });
  }

  // NOTE: must NOT be named "open" — Obsidian's view lifecycle calls
  // view.open(containerEl) when mounting the leaf, so any method with that
  // name overrides the lifecycle hook (this exact bug: the panel stayed
  // blank and the container element was passed to openLinkText).
  // Hidden .deepseek files cannot be opened via Obsidian APIs at all, so
  // clicking a card shows an in-panel preview modal instead.
  openNote(rel) {
    if (typeof rel !== 'string' || rel === '') return;
    const fullPath = join(this.vaultPath(), ...rel.split('/'));
    try {
      const content = readFileSync(fullPath, 'utf8');
      new MemoryPreviewModal(this.app, rel, content, fullPath).open();
    } catch (error) {
      new Notice('无法读取该文件：' + String(error));
    }
  }

  feedback(rel, action) {
    const parts = rel.split('/');
    const filePath = join(this.vaultPath(), ...parts);
    try {
      if (action === 'forget') {
        archiveMemoryFile(this.vaultPath(), parts);
      } else {
        const result = applyFeedback(filePath, action);
        if (!result.ok) {
          new Notice(result.message);
          return;
        }
      }
      new Notice(FEEDBACK_MESSAGES[action]);
    } catch (error) {
      new Notice(`操作失败：${String(error)}`);
      return;
    }
    this.render();
  }

  cardRow(parent, card) {
    const row = parent.createDiv({ cls: 'dsh-memory-row' });
    const title = row.createEl('a', { text: card.title, cls: 'dsh-memory-title' });
    title.addEventListener('click', () => this.openNote(card.rel));
    const parts = [];
    if (card.type !== '') parts.push(card.type);
    if (card.operator !== '') parts.push(card.operator);
    if (card.status !== 'active') parts.push(card.status);
    const badge = VERIFIED_BADGES[card.verified] ?? (card.hook === null ? '' : '❓');
    if (badge !== '') parts.push(badge);
    parts.push(`uses ${card.uses}`);
    if (card.successRate !== null) parts.push(`成功率 ${card.successRate}`);
    if (card.lastUsed !== '') parts.push(`上次 ${card.lastUsed}`);
    if (card.updated !== '') parts.push(daysSinceText(card.updated));
    row.createDiv({ cls: 'dsh-memory-meta', text: parts.join(' · ') });
    const actions = row.createDiv({ cls: 'dsh-memory-actions' });
    if (card.hook !== null) {
      const confirm = actions.createEl('button', { text: '✅' });
      confirm.title = '确认这条记忆正确（verified → user-confirmed，成功率提至 ≥0.9）';
      confirm.addEventListener('click', () => this.feedback(card.rel, 'confirm'));
      const wrong = actions.createEl('button', { text: '❌' });
      wrong.title = '标记错误（成功率减半，次日体检重新评估）';
      wrong.addEventListener('click', () => this.feedback(card.rel, 'wrong'));
    }
    if (card.status !== 'superseded') {
      const stale = actions.createEl('button', { text: '过期' });
      stale.title = '标记 superseded（保留证据，不删除）';
      stale.addEventListener('click', () => this.feedback(card.rel, 'stale'));
    }
    const forget = actions.createEl('button', { text: '归档' });
    forget.title = '移入 .deepseek/archive/records/（不删除）';
    forget.addEventListener('click', () => this.feedback(card.rel, 'forget'));
  }

  memoRow(parent, memo) {
    const row = parent.createDiv({ cls: 'dsh-memory-row' });
    const title = row.createEl('a', { text: memo.title, cls: 'dsh-memory-title' });
    title.addEventListener('click', () => this.openNote(memo.rel));
    const statusText = { inbox: '待打磨', polishing: '打磨中', done: '已完成' }[memo.status] ?? memo.status;
    const parts = [statusText];
    if (memo.topic !== '') parts.push(memo.topic);
    if (memo.updated !== '') parts.push(daysSinceText(memo.updated));
    row.createDiv({ cls: 'dsh-memory-meta', text: parts.join(' · ') });
  }
}

// ── plugin ──────────────────────────────────────────────────────────────────

class DshObsidianMathPlugin extends Plugin {
  async onload() {
    await this.loadSettings();
    debugVaultPath = this.app.vault.adapter.getBasePath();
    try {
      const debugPath = join(debugVaultPath, '.obsidian', 'plugins', 'dsh-math-assistant', 'debug.log');
      if (existsSync(debugPath) && statSync(debugPath).size > 1024 * 1024) writeFileSync(debugPath, '', 'utf8');
    } catch {
      // rotation is best-effort
    }
    writeDebugLog('=== onload start ===');
    this.service = new DshService(this);

    // Instrumentation: capture the throwing site of every Obsidian toast.
    // Opaque errors like "e.toLowerCase is not a function" are produced by
    // Obsidian internals catching plugin errors and calling new Notice(...);
    // recording the stack at setMessage time reveals the exact caller.
    const pluginRef = this;
    this.originalNoticeSetMessage = null;
    this.noticeWrapper = null;
    if (typeof Notice !== 'undefined' && typeof Notice.prototype?.setMessage === 'function') {
      const originalSetMessage = Notice.prototype.setMessage;
      const wrapper = function (message) {
        try {
          const text = typeof message === 'string' ? message : String(message ?? '');
          if (text.length > 0 && text.length < 400) {
            pluginRef.service?.appendLog('[toast] ' + text + '\n' + (new Error('toast-stack').stack ?? '(no stack)'));
          }
        } catch {
          // never let instrumentation break the toast
        }
        return originalSetMessage.call(this, message);
      };
      Notice.prototype.setMessage = wrapper;
      this.originalNoticeSetMessage = originalSetMessage;
      this.noticeWrapper = wrapper;
    }
    this.linkServer = new LinkServer(this);
    this.linkServer.start();
    this.registerView(VIEW_TYPE, (leaf) => new DshMathView(leaf, this));
    this.registerView(VIEW_TYPE_MEMORY, (leaf) => {
      writeDebugLog('[memory-view] factory invoked');
      return new MemoryView(leaf, this);
    });
    writeDebugLog('memory view registered');
    if (this.settings.showRibbon) {
      this.addRibbonIcon('message-square', '打开 DSH数学笔记助手', () => this.activateView());
    }
    this.addCommand({
      id: 'open-dsh-math-assistant',
      name: '打开 DSH数学笔记助手',
      callback: () => this.activateView()
    });
    this.addCommand({
      id: 'open-dsh-memory-panel',
      name: '打开 DSH 记忆面板',
      callback: () => this.activateMemoryView()
    });
    this.addCommand({
      id: 'start-dsh-service',
      name: '启动 DSH 服务',
      callback: async () => {
        try {
          await this.service.start();
          new Notice('DSH 服务已运行');
        } catch (error) {
          new Notice(String(error));
        }
      }
    });
    this.addCommand({
      id: 'stop-dsh-service',
      name: '停止 DSH 服务',
      callback: async () => {
        await this.service.stop();
        new Notice('DSH 服务已停止');
      }
    });
    this.addSettingTab(new DshObsidianSettingTab(this.app, this));
    // Global error traps: memory-panel activation failures so far surfaced as
    // an opaque "e.toLowerCase is not a function" toast from outside our own
    // try/catch. Capture every uncaught error/rejection into the plugin log
    // so the exact throwing site (and its origin URL) becomes visible.
    this.onWindowError = (event) => {
      this.service?.appendLog('[window-error] ' + String(event?.error ?? event?.message) + '\n' + (event?.error?.stack ?? '(no stack)'));
    };
    this.onUnhandledRejection = (event) => {
      const reason = event?.reason;
      this.service?.appendLog('[unhandledrejection] ' + String(reason) + '\n' + (reason?.stack ?? '(no stack)'));
    };
    window.addEventListener('error', this.onWindowError);
    window.addEventListener('unhandledrejection', this.onUnhandledRejection);
    if (this.settings.autoInit) {
      this.app.workspace.onLayoutReady(() => {
        try {
          bootstrapDshConfig(this, false);
          bootstrapVaultTemplates(this, false);
        } catch (error) {
          new Notice(`dsh-obsidian-math: ${String(error)}`);
        }
      });
    }
    // Mirror the web profile's @linxin666 packages into the obsidian profile
    // so the global skin insert can always resolve (durable skin fix).
    this.app.workspace.onLayoutReady(() => {
      try {
        const location = this.service.location();
        if (location !== null) {
          const result = syncGlobalPackageLinks(location.home);
          if (result.linked > 0) this.service?.appendLog(`已为 obsidian profile 建立 ${result.linked} 个包链接（皮肤兼容）`);
        }
      } catch (error) {
        this.service?.appendLog(`包链接同步失败：${String(error)}`);
      }
    });
    if (this.settings.autoArchiveEpisodes) {
      this.app.workspace.onLayoutReady(() => {
        try {
          const result = archiveOldEpisodes(this, 90);
          if (result.moved > 0) new Notice(`记忆维护：已归档 ${result.moved} 个旧事件文件`);
        } catch (error) {
          new Notice(`记忆维护失败：${String(error)}`);
        }
      });
    }
    if (this.settings.autoStart) {
      this.app.workspace.onLayoutReady(() => {
        setTimeout(() => {
          this.service.ensureStarted().catch(() => {});
        }, 1200);
      });
    }
  }

  async activateView() {
    try {
      const { workspace } = this.app;
      let leaf = workspace.getLeavesOfType(VIEW_TYPE)[0] ?? null;
      if (leaf === null) {
        if (typeof workspace.getRightLeaf === 'function') leaf = workspace.getRightLeaf(false);
        if (leaf === null) leaf = workspace.getLeaf('tab');
        await leaf.setViewState({ type: VIEW_TYPE, active: true });
      }
      if (typeof workspace.revealLeaf === 'function') await workspace.revealLeaf(leaf);
      else workspace.setActiveLeaf(leaf);
    } catch (error) {
      new Notice(`无法打开助手面板：${String(error)}`);
    }
  }

  async activateMemoryView() {
    writeDebugLog('[activateMemoryView] enter (typeof VIEW_TYPE_MEMORY=' + typeof VIEW_TYPE_MEMORY + ')');
    try {
      const { workspace } = this.app;
      const viewType = typeof VIEW_TYPE_MEMORY === 'string' ? VIEW_TYPE_MEMORY : 'dsh-memory-panel';
      let leaf = workspace.getLeavesOfType(viewType)[0] ?? null;
      writeDebugLog('[activateMemoryView] existing leaf: ' + (leaf === null ? 'null' : 'found'));
      if (leaf === null) {
        if (typeof workspace.getRightLeaf === 'function') {
          leaf = workspace.getRightLeaf(false);
          writeDebugLog('[activateMemoryView] rightLeaf: ' + (leaf === null ? 'null' : 'leaf'));
        } else {
          writeDebugLog('[activateMemoryView] getRightLeaf missing');
        }
        if (leaf === null) {
          leaf = workspace.getLeaf('tab');
          writeDebugLog('[activateMemoryView] tabLeaf: ' + (leaf === null ? 'null' : 'leaf'));
        }
        await leaf.setViewState({ type: viewType, active: true });
        writeDebugLog('[activateMemoryView] setViewState done');
      }
      if (typeof workspace.revealLeaf === 'function') {
        await workspace.revealLeaf(leaf);
        writeDebugLog('[activateMemoryView] revealLeaf done');
      } else {
        workspace.setActiveLeaf(leaf);
        writeDebugLog('[activateMemoryView] setActiveLeaf done');
      }
    } catch (error) {
      const detail = `无法打开记忆面板：${String(error)}（viewType typeof=${typeof VIEW_TYPE_MEMORY}）`;
      writeDebugLog('[activateMemoryView] FAILED: ' + detail + '\n' + (error?.stack ?? '(no stack)'));
      new Notice(detail);
    }
  }

  openSettings() {
    const setting = this.app.setting;
    if (!setting) return;
    try {
      setting.open();
    } catch {
      // ignored; openTabById below is the important part
    }
    try {
      setting.openTabById(this.manifest.id);
    } catch {
      // older Obsidian: the settings root is already open
    }
  }

  async loadSettings() {
    this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData());
  }

  async saveSettings() {
    await this.saveData(this.settings);
  }

  onunload() {
    this.linkServer?.stop();
    window.removeEventListener('error', this.onWindowError);
    window.removeEventListener('unhandledrejection', this.onUnhandledRejection);
    // Restore the toast instrumentation only if it is still ours (another
    // plugin may have patched setMessage after us).
    if (this.noticeWrapper !== null && typeof Notice !== 'undefined' && Notice.prototype?.setMessage === this.noticeWrapper) {
      Notice.prototype.setMessage = this.originalNoticeSetMessage;
    }
    if (this.service?.child !== null && !this.settings.keepAliveOnUnload) {
      this.service?.stop();
    }
  }
}

module.exports = DshObsidianMathPlugin;

// ── settings tab ────────────────────────────────────────────────────────────

class DshObsidianSettingTab extends PluginSettingTab {
  constructor(app, plugin) {
    super(app, plugin);
    this.plugin = plugin;
  }

  display() {
    const { containerEl } = this;
    containerEl.empty();
    containerEl.createEl('h2', { text: 'DSH数学笔记助手' });
    containerEl.createEl('p', { text: `版本 ${this.plugin.manifest?.version ?? ''}` });
    containerEl.createEl('p', { text: '在 Obsidian 右侧栏嵌入 DeepSeek Harness 数学记忆助手。插件会自动启动 dsh 服务，无需额外打开命令行窗口。' });
    containerEl.createEl('p', { cls: 'dsh-obsidian-math-security-note', text: '🔒 安全模式：助手只能写当前 vault 内的文件；权限升级审批默认关闭，不会弹出“是否提权”的窗口；工具集中没有删除类工具。' });
    containerEl.createEl('p', { cls: 'dsh-obsidian-math-security-note', text: '🧭 适用范围：面向数学类知识（数学、统计学笔记与数学思维方式）设计，其他领域的知识可能需要不同的记忆架构。当前为试做型（0.4.x），记忆架构尚未经过长期使用测试，后续会继续演进。' });

    new Setting(containerEl)
      .setName('端口')
      .setDesc('dsh 网页服务的本地端口。默认 3180，与默认 dsh web 的 3080 互不冲突。')
      .addText((text) => text
        .setPlaceholder('3180')
        .setValue(String(this.plugin.settings.port))
        .onChange(async (value) => {
          const port = Number.parseInt(value, 10);
          if (Number.isInteger(port) && port > 0 && port < 65536) {
            this.plugin.settings.port = port;
            await this.plugin.saveSettings();
          }
        }));

    const location = this.plugin.service.location();
    new Setting(containerEl)
      .setName('dsh 安装目录')
      .setDesc(location ? `已检测到：${location.installDir}` : '尚未检测到。可点击“自动检测”，或手动填写目录后回车。')
      .addText((text) => text
        .setPlaceholder('留空则自动检测')
        .setValue(this.plugin.settings.dshInstallDir)
        .onChange(async (value) => {
          this.plugin.settings.dshInstallDir = value.trim();
          this.plugin.service.cachedLocation = undefined;
          await this.plugin.saveSettings();
        }))
      .addButton((button) => button.setButtonText('自动检测').onClick(async () => {
        const found = this.plugin.service.location(true);
        if (found === null) {
          new Notice('未找到 dsh。请先安装 DeepSeek Harness，或手动填写安装目录。');
        } else {
          this.plugin.settings.dshInstallDir = found.installDir;
          await this.plugin.saveSettings();
          new Notice(`已检测到 dsh：${found.installDir}`);
          this.display();
        }
      }));

    new Setting(containerEl)
      .setName('DSH_HOME')
      .setDesc(location ? `已自动探测：${location.home}（可直接修改）` : 'dsh 主目录（preset、profile、会话日志所在处）。留空则自动探测。')
      .addText((text) => text
        .setPlaceholder('留空则自动探测')
        .setValue(location?.home ?? this.plugin.settings.dshHome)
        .onChange(async (value) => {
          this.plugin.settings.dshHome = value.trim();
          this.plugin.service.cachedLocation = undefined;
          await this.plugin.saveSettings();
        }));

    new Setting(containerEl)
      .setName('启动 Obsidian 时自动启动服务')
      .setDesc('打开 Obsidian 后自动拉起 dsh 服务，无需手动操作。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.autoStart).onChange(async (value) => {
        this.plugin.settings.autoStart = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('自动初始化 dsh 配置与记忆模板')
      .setDesc('首次运行时自动补齐 preset、profile 与 vault 内的记忆模板（只补缺失文件，不覆盖已有修改）。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.autoInit).onChange(async (value) => {
        this.plugin.settings.autoInit = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('启动时自动归档旧事件（超过 90 天）')
      .setDesc('把过旧的事件卡移入 episodes/archive/ 并更新索引——由插件执行，agent 本身没有删除/移动工具。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.autoArchiveEpisodes).onChange(async (value) => {
        this.plugin.settings.autoArchiveEpisodes = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('显示侧边栏按钮')
      .setDesc('在 Obsidian 左侧 ribbon 显示一键打开按钮。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.showRibbon).onChange(async (value) => {
        this.plugin.settings.showRibbon = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('关闭 Obsidian 时保留服务')
      .setDesc('默认关闭：插件退出时会停止它自己启动的 dsh 服务。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.keepAliveOnUnload).onChange(async (value) => {
        this.plugin.settings.keepAliveOnUnload = value;
        await this.plugin.saveSettings();
      }));

    containerEl.createEl('h3', { text: '配置' });
    const configRow = containerEl.createDiv({ cls: 'dsh-obsidian-math-config-actions' });
    const initButton = configRow.createEl('button', { text: '初始化 dsh 配置与 vault 模板' });
    initButton.addEventListener('click', async () => {
      try {
        const dsh = bootstrapDshConfig(this.plugin, false);
        const vault = bootstrapVaultTemplates(this.plugin, false);
        new Notice(`dsh 配置已就绪（${dsh.written.length} 个文件）。vault 模板：${vault.written.length} 个。`);
        this.display();
      } catch (error) {
        new Notice(String(error));
      }
    });
    const forceButton = configRow.createEl('button', { text: '强制重装 dsh 配置' });
    forceButton.addEventListener('click', async () => {
      try {
        const result = bootstrapDshConfig(this.plugin, true);
        new Notice(`dsh 配置已重装到 ${result.home}`);
        this.display();
      } catch (error) {
        new Notice(String(error));
      }
    });
    const archiveButton = configRow.createEl('button', { text: '立即归档旧事件（>90 天）' });
    archiveButton.addEventListener('click', () => {
      try {
        const result = archiveOldEpisodes(this.plugin, 90);
        new Notice(result.moved > 0 ? `已归档 ${result.moved} 个旧事件文件` : '没有需要归档的旧事件');
        this.display();
      } catch (error) {
        new Notice(String(error));
      }
    });
    const memoryButton = configRow.createEl('button', { text: '打开记忆面板' });
    memoryButton.addEventListener('click', () => {
      writeDebugLog('[settings] 打开记忆面板 button clicked');
      this.plugin.activateMemoryView();
    });

    containerEl.createEl('h3', { text: '服务' });
    const serviceRow = containerEl.createDiv({ cls: 'dsh-obsidian-math-config-actions' });
    const startButton = serviceRow.createEl('button', { text: '启动服务' });
    startButton.addEventListener('click', async () => {
      await this.plugin.service.start().catch((error) => new Notice(String(error)));
      this.display();
    });
    const stopButton = serviceRow.createEl('button', { text: '停止服务' });
    stopButton.addEventListener('click', async () => {
      await this.plugin.service.stop();
      this.display();
    });
    const restartButton = serviceRow.createEl('button', { text: '重启服务' });
    restartButton.addEventListener('click', async () => {
      await this.plugin.service.restart().catch((error) => new Notice(String(error)));
      this.display();
    });
    const statusLabels = {
      running: '运行中',
      starting: '启动中',
      stopped: '已停止',
      stopping: '停止中',
      'missing-dsh': '未找到 dsh',
      error: '错误',
      unknown: '未知'
    };
    serviceRow.createEl('span', { text: ` 状态：${statusLabels[this.plugin.service.status] ?? this.plugin.service.status}` });

    const log = this.plugin.service.logLines.join('\n');
    if (log !== '') {
      containerEl.createEl('h3', { text: `最近服务日志（共 ${this.plugin.service.logLines.length} 行，可滚动）` });
      const copyLog = containerEl.createEl('button', { text: '复制全部日志' });
      copyLog.addEventListener('click', async () => {
        try {
          await navigator.clipboard.writeText(log);
          new Notice('日志已复制到剪贴板');
        } catch {
          new Notice('复制失败，请手动选择日志文本');
        }
      });
      containerEl.createEl('pre', { text: log, cls: 'dsh-obsidian-math-log' });
    }
  }
}
